{
"id": "explore",
"title": "Average CPU per Host",
"description": "Computes the average CPU utilization in percent (cpu_pct) for each host, grouped into one-minute buckets over time.",
"viz": "line",
"layout": {"x": 0, "y": 0, "w": 12, "h": 4},
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS bucket, host, avg(cpu_pct) AS avg_cpu FROM system_metrics GROUP BY bucket, host ORDER BY bucket",
"timeField": "bucket"
},
"format": "percent",
"options": {"decimals": 1, "legend": "bottom", "yAxis": {"min": 0, "max": 100, "label": "CPU %"}}
}
